        "hold_budget"
    } else {
        "decode"
    };
    quarantine_invalid_scan_index(path, cause, None, source, support_dir, now)
        .map(|index| (index, LoadOrigin::Quarantined))
        .map_err(|refusal| refusal.context(error))
}
Err(error) => {
